import json, os, sys, glob, collections

ROOT = "/home/jarvis/agent/jarvis"
sys.path.insert(0, "/home/jarvis/agent")
out = {}


def day_stats(day):
    path = f"{ROOT}/memory/log/{day}.jsonl"
    if not os.path.exists(path):
        return None
    total = 0.0
    n_cost = 0
    zero = 0
    types = collections.Counter()
    results = collections.Counter()
    with open(path, encoding="utf-8", errors="replace") as f:
        for line in f:
            try:
                rec = json.loads(line)
            except Exception:
                continue
            types[rec.get("type", "?")] += 1
            c = rec.get("content")
            if isinstance(c, str) and "cost_usd" in c:
                try:
                    inner = json.loads(c)
                except Exception:
                    continue
                v = inner.get("cost_usd")
                results[str(inner.get("result"))] += 1
                if isinstance(v, (int, float)):
                    n_cost += 1
                    total += v
                    if v == 0:
                        zero += 1
    return {
        "cost_total": round(total, 2),
        "cost_records": n_cost,
        "cost_zero": zero,
        "types": types.most_common(10),
        "results": results.most_common(8),
        "size_mb": round(os.path.getsize(path) / 1e6, 1),
    }


out["days"] = {d: day_stats(d) for d in
